import { useEffect,useMemo,useState,type FormEvent,type ReactNode } from 'react'
import { Link,useNavigate,useParams } from 'react-router-dom'
import { BaseLayout } from '@/components/layouts/base-layout'
import { Button } from '@/components/ui/button'
import { Card,CardContent,CardDescription,CardHeader,CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import * as a from './api'

const field='w-full rounded-md border bg-background px-3 py-2 text-sm'
function Notice({error,ok}:{error?:string;ok?:string}){return <>{error&&<p className="text-sm text-destructive">{error}</p>}{ok&&<p className="text-sm text-emerald-600">{ok}</p>}</>}
function Page({title,description,children}:{title:string;description:string;children:ReactNode}){return <BaseLayout title={title} description={description}><div className="space-y-5 px-4 lg:px-6">{children}</div></BaseLayout>}
function useAsync<T>(loader:()=>Promise<T>,deps:unknown[]=[]){const [data,setData]=useState<T>();const [error,setError]=useState('');const [loading,setLoading]=useState(true);const reload=async()=>{setLoading(true);setError('');try{setData(await loader())}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setLoading(false)}};useEffect(()=>{void reload()},deps);return{data,error,loading,reload}}
const customersFrom=(v:{content:a.Customer[]}|a.Customer[]|undefined)=>Array.isArray(v)?v:v?.content??[]

export function Protected({children,roles,capabilities}:{children:ReactNode;roles?:string[];capabilities?:string[]}){const [state,setState]=useState<'loading'|'ok'|'no'|'denied'>('loading');useEffect(()=>{let active=true;void a.currentUser().then(async user=>{if(!active)return;if(!user){setState('no');return}if(roles?.length&&!roles.includes(user.role)){setState('denied');return}if(capabilities?.length){try{const effective=await a.effectiveCapabilities();if(active)setState(capabilities.some(key=>effective.capabilities.includes(key))?'ok':'denied')}catch{if(active)setState('denied')}return}setState('ok')});return()=>{active=false}},[roles?.join(','),capabilities?.join(',')]);if(state==='loading')return <div className="p-10">Validando sesión…</div>;if(state==='no')return <div className="p-10"><Link to="/login">Inicia sesión para continuar</Link></div>;if(state==='denied')return <div className="p-10"><h1 className="font-semibold">Acceso no autorizado</h1><p className="text-sm text-muted-foreground">Tu usuario no tiene el rol o la capacidad necesaria para este módulo.</p></div>;return children}

export function RealDashboard(){const orders=useAsync(a.listServiceOrders,[]);const customers=useAsync(()=>a.listCustomers(),[]);const products=useAsync(a.listProducts,[]);const users=useAsync(a.listUsers,[]);const list=orders.data??[];const metrics=[['Órdenes abiertas',list.filter(o=>!['COMPLETED','CANCELLED'].includes(o.status)).length],['En diagnóstico',list.filter(o=>o.status==='DIAGNOSIS').length],['Esperando autorización',list.filter(o=>o.status==='QUOTED').length],['Listas / entregadas',list.filter(o=>['QA','COMPLETED'].includes(o.status)).length],['Clientes',customersFrom(customers.data).length],['Refacciones',products.data?.length??0]];const technicians=users.data?.filter(u=>u.role==='TECHNICIAN')??[];return <Page title="Dashboard Fixi" description="Indicadores calculados desde la operación real del taller."><div className="grid gap-4 md:grid-cols-3">{metrics.map(([k,v])=><Card key={k}><CardHeader><CardDescription>{k}</CardDescription><CardTitle className="text-3xl">{v}</CardTitle></CardHeader></Card>)}</div><div className="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle>Actividad reciente</CardTitle></CardHeader><CardContent className="space-y-2">{list.slice(0,8).map(o=><Link className="flex justify-between rounded border p-3" to={`/service-orders/${o.id}`} key={o.id}><span>{o.summary}</span><Badge>{o.status}</Badge></Link>)}{!list.length&&<p className="text-sm text-muted-foreground">Todavía no hay órdenes.</p>}</CardContent></Card><Card><CardHeader><CardTitle>Carga de técnicos</CardTitle></CardHeader><CardContent className="space-y-2">{technicians.map(u=><div className="flex justify-between rounded border p-3" key={u.id}><span>{u.username}</span><Badge variant="outline">{list.filter(o=>o.assignedUserId===u.id&&!['COMPLETED','CANCELLED'].includes(o.status)).length} activas</Badge></div>)}{!technicians.length&&<p className="text-sm text-muted-foreground">Invita técnicos para visualizar su carga.</p>}</CardContent></Card></div><Notice error={orders.error||customers.error||products.error||users.error}/></Page>}

export function BranchDashboard(){const user=useAsync(a.currentUser,[]);const orders=useAsync(a.listServiceOrders,[]);const customers=useAsync(()=>a.listCustomers(),[]);const products=useAsync(a.listProducts,[]);const branchId=user.data?.branchId;const list=(orders.data??[]).filter(o=>!branchId||o.branchId===branchId);const open=list.filter(o=>!['COMPLETED','CANCELLED'].includes(o.status));const overdue=list.filter(o=>o.promisedAt&&new Date(o.promisedAt)<new Date()&&!['COMPLETED','CANCELLED'].includes(o.status));return <Page title="Dashboard de sucursal" description={user.data?.branchId?`Operación filtrada para la sucursal activa ${user.data.branchId}.`:'Selecciona una sucursal para consultar sus indicadores.'}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{[['Órdenes abiertas',open.length],['Vencidas',overdue.length],['Clientes',customersFrom(customers.data).length],['Productos',products.data?.length??0]].map(([label,value])=><Card key={String(label)}><CardHeader><CardDescription>{label}</CardDescription><CardTitle className="text-3xl">{value}</CardTitle></CardHeader></Card>)}</div><Card><CardHeader><CardTitle>Órdenes próximas a compromiso</CardTitle></CardHeader><CardContent className="space-y-2">{[...open].sort((x,y)=>new Date(x.promisedAt??'9999-12-31').getTime()-new Date(y.promisedAt??'9999-12-31').getTime()).slice(0,12).map(o=><Link className="flex flex-wrap items-center justify-between gap-2 rounded border p-3" to={`/service-orders/${o.id}`} key={o.id}><span>{o.summary} · {o.id}</span><span className="text-sm text-muted-foreground">{o.promisedAt?new Date(o.promisedAt).toLocaleString('es-MX'):'Sin fecha compromiso'}</span><Badge>{o.status}</Badge></Link>)}{!open.length&&<p className="text-sm text-muted-foreground">No hay órdenes abiertas en esta sucursal.</p>}</CardContent></Card><Notice error={user.error||orders.error||customers.error||products.error}/></Page>}

export function OrderReportingPage(){const q=useAsync(a.listServiceOrders,[]);const branches=useAsync(a.listBranches,[]);const [branch,setBranch]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const orders=q.data??[];const filtered=orders.filter(o=>(!branch||o.branchId===branch)&&(!from||!!o.createdAt&&o.createdAt.slice(0,10)>=from)&&(!to||!!o.createdAt&&o.createdAt.slice(0,10)<=to));const statuses=[...new Set(filtered.map(o=>o.status))].sort();function exportCsv(){const csv=[['id','branchId','customerId','status','priority','service','summary','createdAt','promisedAt','quoteTotal'],...filtered.map(o=>[o.id,o.branchId??'',o.customerId,o.status,o.priority??'',o.serviceName??'',o.summary,o.createdAt??'',o.promisedAt??'',o.quoteTotal??''])].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='fixi-reporte-ordenes.csv';link.click();URL.revokeObjectURL(url)}return <Page title="Reporte de órdenes" description="Volumen y estado del trabajo registrado en Fixi."><div className="grid gap-3 md:grid-cols-4"><select aria-label="Sucursal" className={field} value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Input aria-label="Desde" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><Input aria-label="Hasta" type="date" value={to} onChange={e=>setTo(e.target.value)}/><Button type="button" variant="outline" onClick={exportCsv}>Exportar CSV</Button></div><div className="grid gap-4 md:grid-cols-3">{[['Total',filtered.length],['Abiertas',filtered.filter(o=>!['COMPLETED','CANCELLED'].includes(o.status)).length],['Vencidas',filtered.filter(o=>o.promisedAt&&new Date(o.promisedAt)<new Date()&&!['COMPLETED','CANCELLED'].includes(o.status)).length]].map(([label,value])=><Card key={String(label)}><CardHeader><CardDescription>{label}</CardDescription><CardTitle className="text-3xl">{value}</CardTitle></CardHeader></Card>)}</div><Card><CardHeader><CardTitle>Distribución por estado</CardTitle></CardHeader><CardContent className="space-y-2">{statuses.map(status=><div key={status} className="flex justify-between rounded border p-3"><span>{status}</span><Badge>{filtered.filter(o=>o.status===status).length}</Badge></div>)}{!statuses.length&&<p className="text-sm text-muted-foreground">Aún no hay órdenes para reportar.</p>}</CardContent></Card><Notice error={q.error||branches.error}/></Page>}

export function InventoryReportingPage(){const products=useAsync(a.listProducts,[]);const branches=useAsync(a.listBranches,[]);const [branch,setBranch]=useState('');const stock=useAsync(()=>branch?a.stock(branch):Promise.resolve([]),[branch]);const balances=stock.data??[];const catalog=products.data??[];const low=catalog.filter(p=>branch&&(balances.find(b=>b.productId===p.id)?.quantity??0)<=Number(p.reorderLevel??0));const valuation=catalog.reduce((sum,p)=>sum+(balances.find(b=>b.productId===p.id)?.quantity??0)*Number(p.cost??0),0);const retail=catalog.reduce((sum,p)=>sum+(balances.find(b=>b.productId===p.id)?.quantity??0)*Number(p.price??0),0);return <Page title="Reporte de inventario" description="Existencias, valoración y alertas de reposición por sucursal."><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Card><CardHeader><CardDescription>Productos en catálogo</CardDescription><CardTitle className="text-3xl">{catalog.length}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Unidades en sucursal</CardDescription><CardTitle className="text-3xl">{balances.reduce((sum,b)=>sum+b.quantity,0)}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Valor a costo</CardDescription><CardTitle className="text-2xl">{money.format(valuation)}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>En mínimo o debajo · venta potencial {money.format(retail)}</CardDescription><CardTitle className="text-3xl">{low.length}</CardTitle></CardHeader></Card></div><select aria-label="Sucursal del reporte" className={field} value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Selecciona sucursal</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Card><CardHeader><CardTitle>Existencias y reposición</CardTitle></CardHeader><CardContent className="space-y-2">{branch&&catalog.map(p=>{const qty=balances.find(b=>b.productId===p.id)?.quantity??0;return <div className="flex flex-wrap justify-between gap-2 rounded border p-3" key={p.id}><span>{p.sku} · {p.name} · {p.category??'General'}</span><span>{qty} unidades · costo {money.format(Number(p.cost??0))} · mínimo {p.reorderLevel??0}{qty<=Number(p.reorderLevel??0)&&<Badge className="ml-2" variant="destructive">Reponer</Badge>}</span></div>})}{!branch&&<p className="text-sm text-muted-foreground">Elige una sucursal para ver cantidades.</p>}</CardContent></Card><Notice error={products.error||branches.error||stock.error}/></Page>}

export function ProductivityReportingPage(){const orders=useAsync(a.listServiceOrders,[]);const users=useAsync(a.listUsers,[]);const [branch,setBranch]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const branches=useAsync(a.listBranches,[]);const scoped=(orders.data??[]).filter(o=>(!branch||o.branchId===branch)&&(!from||!!o.createdAt&&o.createdAt.slice(0,10)>=from)&&(!to||!!o.createdAt&&o.createdAt.slice(0,10)<=to));const active=scoped.filter(o=>!['COMPLETED','CANCELLED'].includes(o.status));const team=users.data?.filter(u=>u.role==='TECHNICIAN')??[];return <Page title="Productividad" description="Carga y cierre de órdenes por técnico."><div className="grid gap-3 md:grid-cols-3"><select aria-label="Sucursal" className={field} value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Input aria-label="Desde" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><Input aria-label="Hasta" type="date" value={to} onChange={e=>setTo(e.target.value)}/></div><div className="grid gap-4 md:grid-cols-3"><Card><CardHeader><CardDescription>Técnicos</CardDescription><CardTitle className="text-3xl">{team.length}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Órdenes activas</CardDescription><CardTitle className="text-3xl">{active.length}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Órdenes finalizadas</CardDescription><CardTitle className="text-3xl">{scoped.filter(o=>o.status==='COMPLETED').length}</CardTitle></CardHeader></Card></div><Card><CardHeader><CardTitle>Carga por técnico</CardTitle></CardHeader><CardContent className="space-y-2">{team.map(user=>{const assigned=scoped.filter(o=>o.assignedUserId===user.id);return <div className="flex justify-between rounded border p-3" key={user.id}><span>{user.username}</span><span>{assigned.filter(o=>!['COMPLETED','CANCELLED'].includes(o.status)).length} abiertas · {assigned.filter(o=>o.status==='COMPLETED').length} terminadas</span></div>})}{!team.length&&<p className="text-sm text-muted-foreground">No hay técnicos registrados.</p>}</CardContent></Card><Notice error={orders.error||users.error||branches.error}/></Page>}

export function FinancialReportingPage(){const today=new Date();const [start,setStart]=useState(new Date(today.getFullYear(),today.getMonth(),1).toISOString().slice(0,10));const [end,setEnd]=useState(today.toISOString().slice(0,10));const [report,setReport]=useState<a.FinancialReport>();const [loading,setLoading]=useState(false);const [error,setError]=useState('');async function load(){setLoading(true);setError('');try{setReport(await a.financialReport(start,end))}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo cargar el reporte financiero')}finally{setLoading(false)}}useEffect(()=>{void load()},[]);function exportCsv(){if(!report)return;const csv=[['factura','fecha','cliente_id','estado','total'],...report.invoices.map(i=>[i.invoiceNumber??i.id,i.issueDate,i.guestId??'',i.status,i.totalAmount])].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='fixi-reporte-financiero.csv';link.click();URL.revokeObjectURL(url)}return <Page title="Finanzas" description="Ingresos facturados, cobros y saldos por periodo."><div className="grid gap-3 md:grid-cols-3"><Input aria-label="Desde" type="date" value={start} onChange={e=>setStart(e.target.value)}/><Input aria-label="Hasta" type="date" value={end} onChange={e=>setEnd(e.target.value)}/><div className="flex gap-2"><Button disabled={loading||!start||!end||start>end} onClick={()=>void load()}>{loading?'Generando…':'Generar reporte'}</Button><Button type="button" variant="outline" disabled={!report} onClick={exportCsv}>Exportar CSV</Button></div></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{[['Ingresos facturados',report?.totalRevenue],['Cobrado',report?.totalCollected],['Saldo pendiente',report?.totalOutstanding],['Facturas pagadas',report?.paidInvoices]].map(([label,value])=><Card key={String(label)}><CardHeader><CardDescription>{label}</CardDescription><CardTitle className="text-2xl">{value===undefined?'—':typeof value==='number'&&String(label)!=='Facturas pagadas'?new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(value):value}</CardTitle></CardHeader></Card>)}</div><Card><CardHeader><CardTitle>Facturas del periodo ({report?.totalInvoices??0})</CardTitle><CardDescription>{report?.startDate} — {report?.endDate}</CardDescription></CardHeader><CardContent className="space-y-2">{loading&&<p role="status">Cargando reporte…</p>}{report?.invoices.map(invoice=><div className="flex flex-wrap justify-between gap-2 rounded border p-3" key={invoice.id}><span>{invoice.invoiceNumber??invoice.id} · Cliente {invoice.guestId??'sin referencia'} · {new Date(invoice.issueDate).toLocaleDateString('es-MX')}</span><span>{invoice.status} · {new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(invoice.totalAmount)}</span></div>)}{report&&!report.invoices.length&&<p className="text-sm text-muted-foreground">No hay facturas para el periodo elegido.</p>}</CardContent></Card><Notice error={error}/></Page>}

export function CustomersPage(){const q=useAsync(()=>a.listCustomers(),[]);const [f,setF]=useState({firstName:'',lastName:'',email:'',phone:'',rfc:'',fiscalName:'',fiscalPostalCode:'',fiscalRegime:'',cfdiUse:''});const [search,setSearch]=useState('');const [msg,setMsg]=useState('');const [saving,setSaving]=useState(false);const [formError,setFormError]=useState('');const list=customersFrom(q.data);const filtered=list.filter(c=>`${c.firstName} ${c.lastName} ${c.email??''} ${c.phone??''} ${c.rfc??''} ${c.fiscalName??''}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()));async function submit(e:FormEvent){e.preventDefault();setSaving(true);setFormError('');setMsg('');try{await a.createCustomer({...f,address:null,city:null,country:null,dateOfBirth:null,billingEmail:f.email||null,fiscalCode:null,vatNumber:null,companyName:null,sdiCode:null,pecEmail:null,cap:null,comune:null,provincia:null});setF({firstName:'',lastName:'',email:'',phone:'',rfc:'',fiscalName:'',fiscalPostalCode:'',fiscalRegime:'',cfdiUse:''});setMsg('Cliente creado correctamente');await q.reload()}catch(e){setFormError(e instanceof Error?e.message:'No se pudo crear el cliente')}finally{setSaving(false)}}return <Page title="Clientes" description="Directorio, datos de facturación e historial del cliente."><Card><CardHeader><CardTitle>Nuevo cliente</CardTitle><CardDescription>RFC y datos fiscales son opcionales; al capturar uno, completa el perfil CFDI.</CardDescription></CardHeader><CardContent><form onSubmit={submit} className="grid gap-3 md:grid-cols-3">{(['firstName','lastName','email','phone'] as const).map(k=><Input key={k} required={k==='firstName'||k==='lastName'||(k==='email'&&!f.phone)||(k==='phone'&&!f.email)} type={k==='email'?'email':k==='phone'?'tel':'text'} autoComplete={k==='email'?'email':k==='phone'?'tel':undefined} placeholder={{firstName:'Nombre',lastName:'Apellido',email:'Correo',phone:'Teléfono'}[k]} value={f[k]} onChange={e=>setF({...f,[k]:e.target.value})}/>) }<Input aria-label="RFC" maxLength={13} placeholder="RFC" value={f.rfc} onChange={e=>setF({...f,rfc:e.target.value.toUpperCase()})}/><Input aria-label="Razón social" maxLength={150} placeholder="Razón social" value={f.fiscalName} onChange={e=>setF({...f,fiscalName:e.target.value})}/><Input aria-label="Código postal fiscal" inputMode="numeric" maxLength={5} placeholder="CP fiscal" value={f.fiscalPostalCode} onChange={e=>setF({...f,fiscalPostalCode:e.target.value})}/><select aria-label="Régimen fiscal" className={field} value={f.fiscalRegime} onChange={e=>setF({...f,fiscalRegime:e.target.value})}><option value="">Régimen fiscal</option>{[['601','General de Ley Personas Morales'],['603','Personas Morales con Fines no Lucrativos'],['605','Sueldos y Salarios'],['606','Arrendamiento'],['612','Personas Físicas con Actividades Empresariales'],['616','Sin obligaciones fiscales'],['621','Incorporación Fiscal'],['625','Régimen de Actividades Empresariales con ingresos a través de Plataformas Tecnológicas'],['626','Régimen Simplificado de Confianza']].map(([code,label])=><option key={code} value={code}>{code} · {label}</option>)}</select><Input aria-label="Uso CFDI" maxLength={4} placeholder="Uso CFDI (p. ej. G03)" value={f.cfdiUse} onChange={e=>setF({...f,cfdiUse:e.target.value.toUpperCase()})}/><Button disabled={saving}>{saving?'Guardando…':'Guardar cliente'}</Button></form><Notice ok={msg} error={formError}/></CardContent></Card><Card><CardHeader><CardTitle>Directorio ({filtered.length})</CardTitle><Input aria-label="Buscar clientes" placeholder="Buscar por nombre, correo, teléfono o RFC" value={search} onChange={e=>setSearch(e.target.value)}/></CardHeader><CardContent className="space-y-2">{q.loading&&<p role="status" className="text-sm text-muted-foreground">Cargando clientes…</p>}{q.error&&<div className="flex items-center justify-between gap-3"><Notice error={q.error}/><Button type="button" variant="outline" onClick={()=>void q.reload()}>Reintentar</Button></div>}{!q.loading&&!q.error&&filtered.map(c=><Link to={`/customers/${c.id}`} className="flex flex-wrap justify-between gap-2 rounded border p-3" key={c.id}><span>{c.firstName} {c.lastName}{c.fiscalName?` · ${c.fiscalName}`:''}</span><span className="text-sm text-muted-foreground">{c.phone||c.email||'Sin datos de contacto'}{c.rfc?` · RFC ${c.rfc}`:''}</span></Link>)}{!q.loading&&!q.error&&!filtered.length&&<p className="text-sm text-muted-foreground">{search?'No hay clientes que coincidan con la búsqueda.':'Todavía no hay clientes registrados.'}</p>}</CardContent></Card></Page>}

export function CustomerDetailPage(){const {id=''}=useParams();const customer=useAsync(()=>a.getCustomer(id),[id]);const devices=useAsync(()=>a.listDevices(id),[id]);const orders=useAsync(()=>a.customerServiceOrders(id),[id]);const warranties=useAsync(()=>a.listWarrantyClaims(id),[id]);const [editing,setEditing]=useState(false);const [draft,setDraft]=useState({firstName:'',lastName:'',email:'',phone:'',rfc:'',fiscalName:'',fiscalPostalCode:'',fiscalRegime:'',cfdiUse:''});const [saving,setSaving]=useState(false);const [message,setMessage]=useState('');const [saveError,setSaveError]=useState('');useEffect(()=>{if(customer.data)setDraft({firstName:customer.data.firstName,lastName:customer.data.lastName,email:customer.data.email??'',phone:customer.data.phone??'',rfc:customer.data.rfc??'',fiscalName:customer.data.fiscalName??'',fiscalPostalCode:customer.data.fiscalPostalCode??'',fiscalRegime:customer.data.fiscalRegime??'',cfdiUse:customer.data.cfdiUse??''})},[customer.data]);async function save(e:FormEvent){e.preventDefault();setSaving(true);setSaveError('');setMessage('');try{await a.updateCustomer(id,{...customer.data,...draft,billingEmail:draft.email||null});setMessage('Datos del cliente actualizados');setEditing(false);await customer.reload()}catch(error){setSaveError(error instanceof Error?error.message:'No se pudieron guardar los cambios')}finally{setSaving(false)}}return <Page title={customer.data?`${customer.data.firstName} ${customer.data.lastName}`:'Cliente'} description="Equipos, datos fiscales, reparaciones y garantías en un solo historial."><Card><CardHeader><CardTitle className="flex items-center justify-between">Contacto y facturación{!editing&&<Button type="button" variant="outline" onClick={()=>setEditing(true)}>Editar datos</Button>}</CardTitle></CardHeader><CardContent>{editing?<form onSubmit={save} className="grid gap-3 md:grid-cols-3"><Input required aria-label="Nombre" value={draft.firstName} onChange={e=>setDraft({...draft,firstName:e.target.value})}/><Input required aria-label="Apellido" value={draft.lastName} onChange={e=>setDraft({...draft,lastName:e.target.value})}/><Input type="email" aria-label="Correo" value={draft.email} onChange={e=>setDraft({...draft,email:e.target.value})}/><Input type="tel" aria-label="Teléfono" value={draft.phone} onChange={e=>setDraft({...draft,phone:e.target.value})}/><Input aria-label="RFC" maxLength={13} placeholder="RFC" value={draft.rfc} onChange={e=>setDraft({...draft,rfc:e.target.value.toUpperCase()})}/><Input aria-label="Razón social" placeholder="Razón social" value={draft.fiscalName} onChange={e=>setDraft({...draft,fiscalName:e.target.value})}/><Input aria-label="CP fiscal" inputMode="numeric" maxLength={5} placeholder="CP fiscal" value={draft.fiscalPostalCode} onChange={e=>setDraft({...draft,fiscalPostalCode:e.target.value})}/><Input aria-label="Régimen fiscal (código)" maxLength={3} placeholder="Régimen (p. ej. 626)" value={draft.fiscalRegime} onChange={e=>setDraft({...draft,fiscalRegime:e.target.value})}/><Input aria-label="Uso CFDI" maxLength={4} placeholder="Uso CFDI" value={draft.cfdiUse} onChange={e=>setDraft({...draft,cfdiUse:e.target.value.toUpperCase()})}/><div className="flex gap-2"><Button disabled={saving}>{saving?'Guardando…':'Guardar cambios'}</Button><Button type="button" variant="outline" disabled={saving} onClick={()=>setEditing(false)}>Cancelar</Button></div></form>:<><p>{customer.data?.phone||'Sin teléfono'}</p><p>{customer.data?.email||'Sin correo'}</p><p>{customer.data?.fiscalName||'Sin razón social'}{customer.data?.rfc?` · RFC ${customer.data.rfc}`:''}</p>{customer.data?.fiscalPostalCode&&<p>CP fiscal {customer.data.fiscalPostalCode} · Régimen {customer.data.fiscalRegime} · CFDI {customer.data.cfdiUse}</p>}</>}<Notice ok={message} error={saveError||customer.error}/></CardContent></Card><div className="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle>Equipos ({devices.data?.length??0})</CardTitle></CardHeader><CardContent>{devices.loading?<p role="status">Cargando equipos…</p>:devices.data?.length?devices.data.map(d=><p key={d.id}>{d.manufacturer} {d.model} · {d.serialNumber||d.imei}</p>):<p className="text-sm text-muted-foreground">No hay equipos registrados.</p>}</CardContent></Card><Card><CardHeader><CardTitle>Garantías ({warranties.data?.length??0})</CardTitle></CardHeader><CardContent>{warranties.loading?<p role="status">Cargando garantías…</p>:warranties.data?.length?warranties.data.map(w=><p key={w.id}>{w.description} · {w.status}</p>):<p className="text-sm text-muted-foreground">No hay garantías registradas.</p>}</CardContent></Card></div><Card><CardHeader><CardTitle>Historial de servicio</CardTitle></CardHeader><CardContent className="space-y-2">{orders.loading&&<p role="status">Cargando historial…</p>}{!orders.loading&&orders.data?.map(o=><Link to={`/service-orders/${o.id}`} className="flex justify-between rounded border p-3" key={o.id}><span>{o.summary}</span><Badge>{o.status}</Badge></Link>)}{!orders.loading&&!orders.error&&!orders.data?.length&&<p className="text-sm text-muted-foreground">Este cliente aún no tiene órdenes de servicio.</p>}</CardContent></Card><Notice error={devices.error||orders.error||warranties.error}/></Page>}

export function EquipmentPage(){const customers=useAsync(()=>a.listCustomers(),[]);const [customer,setCustomer]=useState('');const devices=useAsync(()=>customer?a.listDevices(customer):Promise.resolve([]),[customer]);const [f,setF]=useState({category:'Teléfono',manufacturer:'',model:'',serialNumber:'',imei:'',customFields:''});async function submit(e:FormEvent){e.preventDefault();await a.createDevice(customer,f);devices.reload()}return <Page title="Equipos" description="Dispositivos, identidad e historial por cliente."><select className={field} value={customer} onChange={e=>setCustomer(e.target.value)}><option value="">Selecciona cliente</option>{customersFrom(customers.data).map(c=><option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>)}</select>{customer&&<Card><CardContent className="pt-6"><form className="grid gap-3 md:grid-cols-3" onSubmit={submit}>{Object.entries(f).map(([k,v])=><Input key={k} required={k==='category'} placeholder={k} value={v} onChange={e=>setF({...f,[k]:e.target.value})}/>) }<Button>Registrar equipo</Button></form></CardContent></Card>}<div className="grid gap-3 md:grid-cols-3">{devices.data?.map(d=><Card key={d.id}><CardHeader><CardTitle>{d.manufacturer} {d.model}</CardTitle><CardDescription>{d.category} · {d.serialNumber||d.imei||'Sin identificador'}</CardDescription></CardHeader></Card>)}</div><Notice error={customers.error||devices.error}/></Page>}

export function ReceptionPage(){const customers=useAsync(()=>a.listCustomers(),[]);const branches=useAsync(a.listBranches,[]);const nav=useNavigate();const [f,setF]=useState({customerId:'',deviceId:'',branchId:'',summary:'',reportedFailure:'',intakeChecklist:'',promisedAt:'',intakeEvidence:''});const devices=useAsync(()=>f.customerId?a.listDevices(f.customerId):Promise.resolve([]),[f.customerId]);async function submit(e:FormEvent){e.preventDefault();const o=await a.createServiceOrder({...f,deviceId:f.deviceId||null,branchId:f.branchId||null,promisedAt:f.promisedAt?new Date(f.promisedAt).toISOString():null});nav(`/service-orders/${o.id}`)}return <Page title="Recepción" description="Ficha completa de recepción legacy integrada al workflow de Fixy."><Card><CardContent className="pt-6"><form onSubmit={submit} className="space-y-4"><select className={field} required value={f.customerId} onChange={e=>setF({...f,customerId:e.target.value,deviceId:''})}><option value="">Cliente</option>{customersFrom(customers.data).map(c=><option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>)}</select><select className={field} value={f.deviceId} onChange={e=>setF({...f,deviceId:e.target.value})}><option value="">Equipo sin registrar</option>{devices.data?.map(d=><option key={d.id} value={d.id}>{d.manufacturer} {d.model} · {d.serialNumber}</option>)}</select><select className={field} value={f.branchId} onChange={e=>setF({...f,branchId:e.target.value})}><option value="">Sucursal</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><textarea className={field} required placeholder="Falla reportada por el cliente" value={f.reportedFailure} onChange={e=>setF({...f,reportedFailure:e.target.value})}/><textarea className={field} required placeholder="Checklist: estado físico, accesorios, encendido, pantalla, puertos…" value={f.intakeChecklist} onChange={e=>setF({...f,intakeChecklist:e.target.value})}/><textarea className={field} required placeholder="Síntomas, accesorios y condición física" value={f.summary} onChange={e=>setF({...f,summary:e.target.value})}/><div className="grid gap-3 md:grid-cols-2"><div><Label>Fecha prometida</Label><Input required type="datetime-local" value={f.promisedAt} onChange={e=>setF({...f,promisedAt:e.target.value})}/></div><div><Label>Evidencia inicial / fotos</Label><Input placeholder="URL o claves de fotografías" value={f.intakeEvidence} onChange={e=>setF({...f,intakeEvidence:e.target.value})}/></div></div><Button>Crear orden completa</Button></form></CardContent></Card></Page>}

export function OrdersPage({title='Órdenes de servicio',statuses}:{title?:string;statuses?:string[]}){const q=useAsync(a.listServiceOrders,[]);const [search,setSearch]=useState('');const [status,setStatus]=useState('ALL');const list=useMemo(()=>q.data?.filter(o=>(!statuses||statuses.includes(o.status))&&(status==='ALL'||status===o.status)&&`${o.summary} ${o.id} ${o.customerId} ${o.status}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase())),[q.data,statuses,status,search]);return <Page title={title} description="Recepción, diagnóstico, reparación, pruebas y entrega."><div className="flex justify-end"><Button asChild><Link to="/reception">Nueva recepción</Link></Button></div><Card><CardContent className="space-y-3 pt-6"><div className="grid gap-2 md:grid-cols-[1fr_220px]"><Input aria-label="Buscar órdenes" placeholder="Buscar por resumen, cliente o folio" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Filtrar por estado" className={field} value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">Todos los estados</option>{(statuses??['INTAKE','REVIEW','DIAGNOSIS','QUOTED','AUTHORIZED','IN_PROGRESS','QA','COMPLETED','CANCELLED']).map(s=><option key={s}>{s}</option>)}</select></div>{q.loading&&<p role="status" className="text-sm text-muted-foreground">Cargando órdenes…</p>}{list?.map(o=><Link to={`/service-orders/${o.id}`} className="flex items-center justify-between rounded border p-3" key={o.id}><div><p className="font-medium">{o.summary}</p><p className="text-xs text-muted-foreground">Folio {o.id} · Cliente {o.customerId}</p></div><Badge>{o.status}</Badge></Link>)}{!q.loading&&!q.error&&!list?.length&&<p className="text-muted-foreground">No hay órdenes que coincidan con estos filtros.</p>}{q.error&&<div className="flex items-center justify-between"><Notice error={q.error}/><Button type="button" variant="outline" onClick={()=>void q.reload()}>Reintentar</Button></div>}</CardContent></Card></Page>}

const statuses=['INTAKE','REVIEW','DIAGNOSIS','QUOTED','AUTHORIZED','IN_PROGRESS','QA','COMPLETED','CANCELLED']
export function OrderDetailPage(){const {id=''}=useParams();const q=useAsync(()=>a.getServiceOrder(id),[id]);const [draft,setDraft]=useState({status:'INTAKE',diagnosis:'',workLog:'',assignedUserId:''});useEffect(()=>{if(q.data)setDraft({status:q.data.status,diagnosis:q.data.diagnosis??'',workLog:q.data.workLog??'',assignedUserId:q.data.assignedUserId??''})},[q.data]);async function save(e:FormEvent){e.preventDefault();await a.updateServiceOrder(id,{...draft,assignedUserId:draft.assignedUserId||null});q.reload()}async function authorize(){await a.authorizeServiceOrder(id,'Autorización registrada por el operador Fixi');q.reload()}return <Page title="Detalle de orden" description={id}><Card><CardContent className="space-y-4 pt-6"><form onSubmit={save} className="space-y-3"><Label>Estado</Label><select className={field} value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value})}>{statuses.map(s=><option key={s}>{s}</option>)}</select><Label>Diagnóstico</Label><textarea className={field} value={draft.diagnosis} onChange={e=>setDraft({...draft,diagnosis:e.target.value})}/><Label>Bitácora / reparación / pruebas</Label><textarea className={field} value={draft.workLog} onChange={e=>setDraft({...draft,workLog:e.target.value})}/><Label>Técnico asignado (UUID)</Label><Input value={draft.assignedUserId} onChange={e=>setDraft({...draft,assignedUserId:e.target.value})}/><div className="flex gap-2"><Button>Guardar avance</Button>{q.data?.status==='QUOTED'&&<Button type="button" variant="outline" onClick={authorize}>Registrar autorización</Button>}</div></form><Notice error={q.error}/></CardContent></Card></Page>}

export function BranchesPage(){const q=useAsync(a.listBranches,[]);const [name,setName]=useState('');const [editingId,setEditingId]=useState('');const [editName,setEditName]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');async function add(e:FormEvent){e.preventDefault();setBusy(true);setError('');setMessage('');try{await a.createBranch(name.trim());setName('');setMessage('Sucursal creada');await q.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo crear la sucursal')}finally{setBusy(false)}}async function rename(e:FormEvent){e.preventDefault();if(!editingId)return;setBusy(true);setError('');setMessage('');try{await a.updateBranch(editingId,editName.trim());setEditingId('');setEditName('');setMessage('Sucursal actualizada');await q.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo actualizar la sucursal')}finally{setBusy(false)}}async function choose(id:string){setError('');try{await a.selectBranch(id);setMessage('Sucursal activa actualizada')}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo cambiar de sucursal')}}async function toggle(id:string,active:boolean){setError('');try{await a.setBranchActive(id,!active);setMessage(active?'Sucursal desactivada':'Sucursal activada');await q.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo cambiar el estado')}}return <Page title="Sucursales" description="Ubicaciones del negocio y contexto operativo activo."><Card><CardContent className="pt-6"><form className="flex flex-col gap-2 sm:flex-row" onSubmit={add}><Input required maxLength={120} value={name} onChange={e=>setName(e.target.value)} placeholder="Nombre de sucursal"/><Button disabled={busy}>{busy?'Creando…':'Crear sucursal'}</Button></form><Notice ok={message} error={error||q.error}/></CardContent></Card>{q.loading&&<p role="status">Cargando sucursales…</p>}<div className="grid gap-3 md:grid-cols-3">{q.data?.map(b=><Card key={b.id}><CardHeader><CardTitle>{b.name}</CardTitle><CardDescription>{b.active?'Activa':'Inactiva'} · {b.id}</CardDescription></CardHeader><CardContent className="space-y-2"><div className="flex flex-wrap gap-2"><Button size="sm" onClick={()=>void choose(b.id)}>Usar sucursal</Button><Button size="sm" variant="outline" onClick={()=>{setEditingId(b.id);setEditName(b.name)}}>Renombrar</Button><Button size="sm" variant="outline" onClick={()=>void toggle(b.id,b.active)}>{b.active?'Desactivar':'Activar'}</Button></div>{editingId===b.id&&<form className="flex gap-2" onSubmit={rename}><Input required maxLength={120} aria-label={`Nuevo nombre de ${b.name}`} value={editName} onChange={e=>setEditName(e.target.value)}/><Button size="sm" disabled={busy}>{busy?'Guardando…':'Guardar'}</Button><Button size="sm" type="button" variant="ghost" onClick={()=>setEditingId('')}>Cancelar</Button></form>}</CardContent></Card>)}</div>{!q.loading&&!q.error&&!q.data?.length&&<p className="text-sm text-muted-foreground">Todavía no hay sucursales.</p>}</Page>}

const capabilityOptions=['CUSTOMERS_READ','CUSTOMERS_WRITE','DEVICES_READ','DEVICES_WRITE','ORDERS_READ','ORDERS_CREATE','ORDERS_UPDATE','ORDERS_STATUS_CHANGE','QUOTES_CREATE','INVENTORY_READ','INVENTORY_ADJUST','INVENTORY_PURCHASE','CASH_OPEN','CASH_CLOSE','CASH_MOVE','PAYMENTS_RECEIVE','FINANCE_READ','BRANCHES_READ','SETTINGS_READ']
export function TeamPage(){const q=useAsync(a.listUsers,[]);const branches=useAsync(a.listBranches,[]);const [f,setF]=useState({email:'',role:'TECHNICIAN',branchId:''});const [access,setAccess]=useState({userId:'',branchId:'',capabilityKey:'ORDERS_READ',enabled:true});const grants=useAsync(()=>access.userId?a.listUserCapabilityGrants(access.userId):Promise.resolve([]),[access.userId]);const [ok,setOk]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function run(action:()=>Promise<void>,success:string){setBusy(true);setError('');setOk('');try{await action();setOk(success)}catch(e){setError(e instanceof Error?e.message:'No se pudo completar la operación')}finally{setBusy(false)}}async function invite(e:FormEvent){e.preventDefault();await run(async()=>{await a.inviteUser({...f,branchId:f.branchId||null});setF({...f,email:''})},'Invitación enviada')}async function assign(){if(!access.userId||!access.branchId)return;await run(()=>a.assignUserBranch(access.branchId,access.userId),'Acceso a sucursal asignado')}async function remove(){if(!access.userId||!access.branchId)return;await run(()=>a.removeUserBranch(access.branchId,access.userId),'Acceso a sucursal retirado')}async function saveGrant(){if(!access.userId)return;await run(async()=>{await a.setUserCapabilityGrant(access.userId,access.capabilityKey,access.enabled,access.branchId);await grants.reload()},'Capacidad actualizada')}return <Page title="Equipo y usuarios" description="Roles, capacidades, invitaciones y acceso por sucursal."><Card><CardHeader><CardTitle>Personas activas ({q.data?.filter(u=>u.active).length??0})</CardTitle></CardHeader><CardContent className="space-y-2">{q.data?.map(u=><div key={u.id} className="flex flex-wrap items-center justify-between gap-2 rounded border p-3"><span>{u.username} · {u.email}</span><div className="flex gap-2"><Badge>{u.role}</Badge><Badge variant={u.active?'default':'outline'}>{u.active?'Activa':'Inactiva'}</Badge></div></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Invitar persona</CardTitle></CardHeader><CardContent><form className="grid gap-3 md:grid-cols-4" onSubmit={invite}><Input type="email" required placeholder="correo@negocio.com" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/><select className={field} value={f.role} onChange={e=>setF({...f,role:e.target.value})}><option>MANAGER</option><option>RECEPTIONIST</option><option>TECHNICIAN</option></select><select className={field} value={f.branchId} onChange={e=>setF({...f,branchId:e.target.value})}><option value="">Todo el tenant</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Button disabled={busy}>{busy?'Enviando…':'Enviar invitación'}</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Acceso y capacidades</CardTitle></CardHeader><CardContent className="space-y-3"><div className="grid gap-2 md:grid-cols-4"><select className={field} value={access.userId} onChange={e=>setAccess({...access,userId:e.target.value})}><option value="">Selecciona usuario</option>{q.data?.map(u=><option key={u.id} value={u.id}>{u.username} · {u.role}</option>)}</select><select className={field} value={access.branchId} onChange={e=>setAccess({...access,branchId:e.target.value})}><option value="">Todo el tenant</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Button type="button" variant="outline" disabled={busy||!access.userId||!access.branchId} onClick={assign}>Asignar sucursal</Button><Button type="button" variant="outline" disabled={busy||!access.userId||!access.branchId} onClick={remove}>Retirar sucursal</Button></div><div className="grid gap-2 md:grid-cols-4"><select className={field} value={access.capabilityKey} onChange={e=>setAccess({...access,capabilityKey:e.target.value})}>{capabilityOptions.map(c=><option key={c}>{c}</option>)}</select><select className={field} value={String(access.enabled)} onChange={e=>setAccess({...access,enabled:e.target.value==='true'})}><option value="true">Permitir</option><option value="false">Revocar</option></select><Button type="button" disabled={busy||!access.userId} onClick={saveGrant}>Guardar capacidad</Button></div>{grants.data?.map(g=><div className="flex justify-between rounded border p-2 text-sm" key={g.id}><span>{g.capabilityKey}{g.branchId?' · sucursal':''}</span><Badge variant={g.enabled?'default':'destructive'}>{g.enabled?'Permitida':'Revocada'}</Badge></div>)}<Notice ok={ok} error={error||q.error||branches.error||grants.error}/></CardContent></Card></Page>}

export function InventoryPage(){const q=useAsync(a.listProducts,[]);const branches=useAsync(a.listBranches,[]);const [branch,setBranch]=useState('');const balances=useAsync(()=>branch?a.stock(branch):Promise.resolve([]),[branch]);const [search,setSearch]=useState('');const [f,setF]=useState({sku:'',name:'',category:'',cost:'0',price:'0',reorderLevel:'0',optional:false});const [movement,setMovement]=useState({productId:'',delta:1});const [error,setError]=useState('');const [message,setMessage]=useState('');const [saving,setSaving]=useState(false);const list=q.data?.filter(p=>`${p.sku} ${p.name} ${p.category??''}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()))??[];async function add(e:FormEvent){e.preventDefault();setSaving(true);setError('');setMessage('');try{await a.createProduct({...f,cost:Number(f.cost),price:Number(f.price),reorderLevel:Number(f.reorderLevel)});setF({sku:'',name:'',category:'',cost:'0',price:'0',reorderLevel:'0',optional:false});setMessage('Producto agregado al catálogo');await q.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo crear el producto')}finally{setSaving(false)}}async function move(e:FormEvent){e.preventDefault();setSaving(true);setError('');setMessage('');try{await a.moveStock({branchId:branch,...movement});setMessage('Movimiento registrado');await balances.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo actualizar la existencia')}finally{setSaving(false)}}const quantity=(id:string)=>balances.data?.find(b=>b.productId===id)?.quantity??0;return <Page title="Inventario y productos" description="Catálogo comercial, costos, precios y existencias por sucursal."><Card><CardHeader><CardTitle>Nuevo producto o refacción</CardTitle></CardHeader><CardContent><form className="grid gap-2 md:grid-cols-4" onSubmit={add}><Input required maxLength={80} placeholder="SKU" value={f.sku} onChange={e=>setF({...f,sku:e.target.value})}/><Input required maxLength={200} placeholder="Nombre" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/><Input required maxLength={120} placeholder="Categoría" value={f.category} onChange={e=>setF({...f,category:e.target.value})}/><Input required type="number" min="0" step="0.01" placeholder="Costo" value={f.cost} onChange={e=>setF({...f,cost:e.target.value})}/><Input required type="number" min="0" step="0.01" placeholder="Precio de venta" value={f.price} onChange={e=>setF({...f,price:e.target.value})}/><Input required type="number" min="0" step="1" placeholder="Alerta de stock bajo" value={f.reorderLevel} onChange={e=>setF({...f,reorderLevel:e.target.value})}/><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={f.optional} onChange={e=>setF({...f,optional:e.target.checked})}/> Refacción opcional</label><Button disabled={saving}>{saving?'Guardando…':'Agregar producto'}</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Ajustar existencias</CardTitle><CardDescription>Usa cantidades positivas para entradas y negativas para salidas; no se permite stock negativo.</CardDescription></CardHeader><CardContent><form className="grid gap-2 md:grid-cols-4" onSubmit={move}><select required className={field} value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Sucursal</option>{branches.data?.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><select required className={field} value={movement.productId} onChange={e=>setMovement({...movement,productId:e.target.value})}><option value="">Producto</option>{q.data?.map(p=><option key={p.id} value={p.id}>{p.sku} · {p.name}</option>)}</select><Input type="number" required min="-1000000" value={movement.delta} onChange={e=>setMovement({...movement,delta:Number(e.target.value)})}/><Button disabled={saving||!branch}>{saving?'Guardando…':'Registrar movimiento'}</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Catálogo ({list.length})</CardTitle><Input aria-label="Buscar productos" placeholder="Buscar SKU, producto o categoría" value={search} onChange={e=>setSearch(e.target.value)}/></CardHeader><CardContent><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{list.map(p=>{const stock=quantity(p.id);const low=Boolean(branch)&&stock<=Number(p.reorderLevel??0);return <Card key={p.id}><CardHeader><CardTitle>{p.name}</CardTitle><CardDescription>{p.sku} · {p.category||'General'}</CardDescription></CardHeader><CardContent className="grid grid-cols-2 gap-2 text-sm"><span>Costo</span><span className="text-right">${Number(p.cost??0).toFixed(2)}</span><span>Precio</span><span className="text-right">${Number(p.price??0).toFixed(2)}</span><span>Existencia</span><span className={`text-right font-semibold ${low?'text-destructive':''}`}>{branch?stock:'Selecciona sucursal'}</span><span>Mínimo</span><span className="text-right">{p.reorderLevel??0}</span>{low&&<p className="col-span-2 font-medium text-destructive">Alerta: stock bajo</p>}</CardContent></Card>})}</div>{q.loading&&<p role="status">Cargando catálogo…</p>}{!q.loading&&!q.error&&!list.length&&<p className="text-sm text-muted-foreground">No hay productos que coincidan.</p>}</CardContent></Card><Notice ok={message} error={error||q.error||branches.error||balances.error}/></Page>}

function supplierCsvCell(value:unknown){return `"${String(value??'').replaceAll('"','""')}"`}
export function SuppliersPage(){const q=useAsync(a.listSuppliers,[]);const empty={name:'',taxId:'',contactName:'',email:'',phone:'',website:'',description:''};const [f,setF]=useState(empty);const [editing,setEditing]=useState('');const [search,setSearch]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const filtered=q.data?.filter(s=>`${s.name} ${s.taxId??''} ${s.contactName??''} ${s.email??''} ${s.phone??''} ${s.description??''}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()))??[];async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');setMessage('');try{if(editing)await a.updateSupplier(editing,f);else await a.createSupplier(f);setF(empty);setEditing('');setMessage(editing?'Proveedor actualizado':'Proveedor guardado');await q.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo guardar el proveedor')}finally{setBusy(false)}}function edit(s:a.Supplier){setF({name:s.name,taxId:s.taxId??'',contactName:s.contactName??'',email:s.email??'',phone:s.phone??'',website:s.website??'',description:s.description??''});setEditing(s.id)}function exportCsv(){const rows=[['id','empresa','rfc','contacto','correo','telefono','sitio_web','descripcion'],...filtered.map(s=>[s.id,s.name,s.taxId??'',s.contactName??s.contact??'',s.email??'',s.phone??'',s.website??'',s.description??''])];const csv='\uFEFF'+rows.map(row=>row.map(supplierCsvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='fixi-proveedores.csv';link.click();URL.revokeObjectURL(url)}return <Page title="Proveedores" description="Directorio comercial de proveedores y contactos para compras."><Card><CardHeader><CardTitle>{editing?'Editar proveedor':'Nuevo proveedor'}</CardTitle></CardHeader><CardContent><form className="grid gap-2 md:grid-cols-3" onSubmit={save}><Input required maxLength={200} placeholder="Empresa / proveedor" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/><Input maxLength={20} placeholder="RFC / identificador fiscal" value={f.taxId} onChange={e=>setF({...f,taxId:e.target.value.toUpperCase()})}/><Input placeholder="Persona de contacto" value={f.contactName} onChange={e=>setF({...f,contactName:e.target.value})}/><Input type="email" placeholder="Correo" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/><Input type="tel" placeholder="Teléfono" value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/><Input type="url" placeholder="Sitio web (https://…)" value={f.website} onChange={e=>setF({...f,website:e.target.value})}/><Input className="md:col-span-2" maxLength={1000} placeholder="Descripción / notas de contacto" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/><div className="flex gap-2"><Button disabled={busy}>{busy?'Guardando…':editing?'Guardar cambios':'Guardar proveedor'}</Button>{editing&&<Button type="button" variant="outline" disabled={busy} onClick={()=>{setEditing('');setF(empty)}}>Cancelar</Button>}</div></form><Notice ok={message} error={error||q.error}/></CardContent></Card><Card><CardHeader><div className="flex flex-wrap items-center justify-between gap-2"><CardTitle>Directorio ({filtered.length})</CardTitle><Button type="button" variant="outline" disabled={q.loading||!!q.error||!filtered.length} onClick={exportCsv}>Exportar CSV</Button></div><Input aria-label="Buscar proveedores" placeholder="Buscar empresa, RFC, contacto, correo o teléfono" value={search} onChange={e=>setSearch(e.target.value)}/></CardHeader><CardContent className="space-y-2">{q.loading&&<p role="status">Cargando proveedores…</p>}{filtered.map(s=><div className="flex flex-wrap items-center justify-between gap-3 rounded border p-3" key={s.id}><div><p className="font-medium">{s.name}</p><p className="text-sm text-muted-foreground">{s.contactName||'Sin contacto'} · {s.email||s.phone||s.contact||'Sin datos de contacto'}{s.taxId?` · RFC ${s.taxId}`:''}</p><p className="text-xs text-muted-foreground">{s.website||''}{s.description?` · ${s.description}`:''}</p></div><Button type="button" variant="outline" onClick={()=>edit(s)}>Editar</Button></div>)}{!q.loading&&!q.error&&!filtered.length&&<p className="text-sm text-muted-foreground">No hay proveedores que coincidan.</p>}</CardContent></Card></Page>}

export function PurchasesPage(){const q=useAsync(a.listPurchases,[]);return <Page title="Compras" description="Órdenes de compra asociadas a sucursal y reparación."><Card><CardContent className="pt-6"><pre className="overflow-auto text-xs">{JSON.stringify(q.data??[],null,2)}</pre><Notice error={q.error}/></CardContent></Card></Page>}

export function OnboardingPage(){const nav=useNavigate();const [f,setF]=useState({contactPhone:'',businessHours:''});async function submit(e:FormEvent){e.preventDefault();await a.completeOnboarding(f);nav('/dashboard')}return <Page title="Configura tu negocio" description="Completa la configuración inicial de Fixi."><Card><CardContent className="pt-6"><form className="space-y-3" onSubmit={submit}><Label>Teléfono del negocio</Label><Input value={f.contactPhone} onChange={e=>setF({...f,contactPhone:e.target.value})}/><Label>Horarios</Label><Input value={f.businessHours} onChange={e=>setF({...f,businessHours:e.target.value})} placeholder="Lun–Sáb 9:00–19:00"/><Button>Completar onboarding</Button></form></CardContent></Card></Page>}

export function SettingsPage(){return <Page title="Configuración" description="Negocio, seguridad e integraciones."><div className="grid gap-4 md:grid-cols-3">{[['Negocio','Datos generales y horarios','/onboarding'],['Sucursales','Ubicaciones y contexto activo','/branches'],['Equipo','Usuarios, roles e invitaciones','/team'],['WhatsApp','Evolution e inbox','/whatsapp'],['IA','Asistente operacional','/ai']].map(([t,d,l])=><Link key={t} to={l}><Card><CardHeader><CardTitle>{t}</CardTitle><CardDescription>{d}</CardDescription></CardHeader></Card></Link>)}</div></Page>}

export function IntegrationPage({kind}:{kind:'WhatsApp'|'IA'}){return kind==='WhatsApp'?<WhatsAppPage/>:<AiPage/>}
function WhatsAppPage(){const q=useAsync(a.whatsappStatus,[]);const inbox=useAsync(a.whatsappConversations,[]);const [conversation,setConversation]=useState('');const [text,setText]=useState('');const messages=useAsync(()=>conversation?a.whatsappMessages(conversation):Promise.resolve([]),[conversation]);return <Page title="WhatsApp" description="Conexión Evolution e inbox tenant-scoped."><Card><CardHeader><CardTitle>Estado: {q.data?.state??'Consultando'}</CardTitle></CardHeader><CardContent className="space-y-3">{q.data?.qrCode&&<img className="max-w-64" src={q.data.qrCode} alt="QR de conexión"/>}<Button onClick={async()=>{await a.whatsappConnect();q.reload()}}>Conectar / actualizar QR</Button></CardContent></Card><div className="grid gap-4 lg:grid-cols-3"><Card><CardHeader><CardTitle>Inbox</CardTitle></CardHeader><CardContent className="space-y-2">{inbox.data?.map(c=><button className="w-full rounded border p-3 text-left" key={c.id} onClick={()=>setConversation(c.id)}><span className="font-medium">{c.displayName||c.channelKey}</span><span className="block text-xs text-muted-foreground">{c.handoff?'Atención humana':c.aiMode}</span></button>)}</CardContent></Card><Card className="lg:col-span-2"><CardHeader><CardTitle>Conversación</CardTitle></CardHeader><CardContent className="space-y-3">{messages.data?.map(m=><div className="rounded border p-2" key={m.id}><Badge>{m.direction}</Badge> {m.body}</div>)}{conversation&&<><form className="flex gap-2" onSubmit={async e=>{e.preventDefault();await a.whatsappReply(conversation,text);setText('');messages.reload()}}><Input required value={text} onChange={e=>setText(e.target.value)} placeholder="Respuesta humana"/><Button>Enviar</Button></form><Button variant="outline" onClick={async()=>{await a.whatsappHandoff(conversation);await inbox.reload()}}>Tomar conversación</Button></>}</CardContent></Card></div><Notice error={q.error||inbox.error||messages.error}/></Page>}
function AiPage(){const [prompt,setPrompt]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);try{const r=await a.assistantChat(prompt);setAnswer(r.answer)}finally{setBusy(false)}}return <Page title="IA Fixi" description="Asistente operacional conectado al backend con herramientas controladas."><Card><CardContent className="space-y-3 pt-6"><form onSubmit={submit} className="flex gap-2"><Input required value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Pregunta sobre la operación del taller"/><Button disabled={busy}>{busy?'Consultando…':'Enviar'}</Button></form>{answer&&<div className="rounded border bg-muted/30 p-4 whitespace-pre-wrap">{answer}</div>}</CardContent></Card></Page>}
